CREATE TABLE IF NOT EXISTS snapshots (name TEXT PRIMARY KEY,iv TEXT NOT NULL,payload BLOB NOT NULL,updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS commands (id TEXT PRIMARY KEY,device_id TEXT NOT NULL,path TEXT NOT NULL,method TEXT NOT NULL,iv TEXT NOT NULL,payload BLOB NOT NULL,status TEXT NOT NULL DEFAULT 'queued',created_at INTEGER NOT NULL,claimed_at INTEGER,result_iv TEXT,result BLOB);
CREATE INDEX IF NOT EXISTS command_queue ON commands(status,created_at);
CREATE TABLE IF NOT EXISTS media (job TEXT NOT NULL,part INTEGER NOT NULL,iv TEXT NOT NULL,payload BLOB NOT NULL,PRIMARY KEY(job,part));
CREATE TABLE IF NOT EXISTS media_info (job TEXT PRIMARY KEY,size INTEGER NOT NULL,parts INTEGER NOT NULL,sha256 TEXT NOT NULL,status TEXT NOT NULL,updated_at INTEGER NOT NULL);
CREATE TABLE IF NOT EXISTS meta (name TEXT PRIMARY KEY,value TEXT NOT NULL);
